Definition Z0_1RB1LA_0LA1RC_0LD1RD_0LB0RB : sconf := mkC StB (mkS [S0;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_1RB1LA_0LA1RC_0LD1RD_0LB0RB : sconf := mkC StB (mkS [S1;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chz_1RB1LA_0LA1RC_0LD1RD_0LB0RB : list lstep := [SWin 2].

Lemma run_z_1RB1LA_0LA1RC_0LD1RD_0LB0RB : srun tm false true chz_1RB1LA_0LA1RC_0LD1RD_0LB0RB Z0_1RB1LA_0LA1RC_0LD1RD_0LB0RB = Some (Z1_1RB1LA_0LA1RC_0LD1RD_0LB0RB, 0, 2).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
    a concrete cell to step onto. *)
Definition P0_1RB1LA_0LA1RC_0LD1RD_0LB0RB : sconf := mkC StB (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition P1_1RB1LA_0LA1RC_0LD1RD_0LB0RB : sconf := mkC StB (mkS [S0;S1;S1] [S0;S1;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chp_1RB1LA_0LA1RC_0LD1RD_0LB0RB : list lstep := [SWin 3; SCycL 3 0; SWin 2; SCycR 3; SWin 3].

Lemma run_p_1RB1LA_0LA1RC_0LD1RD_0LB0RB : srun tm false true chp_1RB1LA_0LA1RC_0LD1RD_0LB0RB P0_1RB1LA_0LA1RC_0LD1RD_0LB0RB = Some (P1_1RB1LA_0LA1RC_0LD1RD_0LB0RB, 6, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1LA_0LA1RC_0LD1RD_0LB0RB : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1LA_0LA1RC_0LD1RD_0LB0RB : sconf := mkC StB (mkS [] [S0;S1;S1] 1 1 [S1]) S0 (mkS [] [] 0 0 []).
(** ** The FIRST INNER anchor family -- Ap_Alph_101_111_1 at StC *)
Definition Cin_1RB1LA_0LA1RC_0LD1RD_0LB0RB (v : positive) : cconf := (StC, (Ap_Alph_101_111_1 v ++ [S1], S0, [])).
Local Notation Cin := Cin_1RB1LA_0LA1RC_0LD1RD_0LB0RB.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1LA_0LA1RC_0LD1RD_0LB0RB : forall n, Ap_Alph_101_111_1 (pow2 n) = rep [S1;S0;S1] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1LA_0LA1RC_0LD1RD_0LB0RB : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB1LA_0LA1RC_0LD1RD_0LB0RB : sconf := mkC StC (mkS [] [S1;S0;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chn_1RB1LA_0LA1RC_0LD1RD_0LB0RB : list lstep := [SRotL 1; SWin 5; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_inner_1RB1LA_0LA1RC_0LD1RD_0LB0RB : srun tm false true chn_1RB1LA_0LA1RC_0LD1RD_0LB0RB AI0_1RB1LA_0LA1RC_0LD1RD_0LB0RB = Some (AI1_1RB1LA_0LA1RC_0LD1RD_0LB0RB, 6, 8).
Proof. vm_compute. reflexivity. Qed.

(** ** The SECOND INNER anchor family -- Ap_Alph_110_111_1 at StD *)
