Lemma run_inner2_1RB1LA_0LA1RC_0LD1RD_0LB0RB : srun tm false true chn2_1RB1LA_0LA1RC_0LD1RD_0LB0RB AI20_1RB1LA_0LA1RC_0LD1RD_0LB0RB = Some (AI21_1RB1LA_0LA1RC_0LD1RD_0LB0RB, 6, 12).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1LA_0LA1RC_0LD1RD_0LB0RB : sconf := mkC StC (mkS [] [S1;S0;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_1RB1LA_0LA1RC_0LD1RD_0LB0RB : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_boot_1RB1LA_0LA1RC_0LD1RD_0LB0RB : srun tm true true chb_1RB1LA_0LA1RC_0LD1RD_0LB0RB B0_1RB1LA_0LA1RC_0LD1RD_0LB0RB = Some (BB1_1RB1LA_0LA1RC_0LD1RD_0LB0RB, 6, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** shift: count 1's all-ones fill -> count 2's anchor.
    WAVE18 section 4c -- "count 8->15, shift, count 8->15 again". *)
Definition BM0_1RB1LA_0LA1RC_0LD1RD_0LB0RB : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition BM1_1RB1LA_0LA1RC_0LD1RD_0LB0RB : sconf := mkC StD (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chm_1RB1LA_0LA1RC_0LD1RD_0LB0RB : list lstep := [SRotL 1; SWin 5; SCycL 3 0; SWin 1; SWinL 3; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_shift_1RB1LA_0LA1RC_0LD1RD_0LB0RB : srun tm true true chm_1RB1LA_0LA1RC_0LD1RD_0LB0RB BM0_1RB1LA_0LA1RC_0LD1RD_0LB0RB = Some (BM1_1RB1LA_0LA1RC_0LD1RD_0LB0RB, 6, 10).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LA_0LA1RC_0LD1RD_0LB0RB : sconf := mkC StD (mkS [] [S1;S1;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1LA_0LA1RC_0LD1RD_0LB0RB : list lstep := [SRotL 1; SWin 7; SCycL 3 0; SWin 2; SWinL 4; SCycR 3; SWin 1; SRotL 2; SFoldL 1].

Lemma run_exit_1RB1LA_0LA1RC_0LD1RD_0LB0RB : srun tm true true che_1RB1LA_0LA1RC_0LD1RD_0LB0RB BE0_1RB1LA_0LA1RC_0LD1RD_0LB0RB = Some (B1_1RB1LA_0LA1RC_0LD1RD_0LB0RB, 6, 14).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1LA_0LA1RC_0LD1RD_0LB0RB : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_1RB1LA_0LA1RC_0LD1RD_0LB0RB /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_1RB1LA_0LA1RC_0LD1RD_0LB0RB = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1LA_0LA1RC_0LD1RD_0LB0RB, cden, Z0_1RB1LA_0LA1RC_0LD1RD_0LB0RB, Z1_1RB1LA_0LA1RC_0LD1RD_0LB0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1LA_0LA1RC_0LD1RD_0LB0RB : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P0_1RB1LA_0LA1RC_0LD1RD_0LB0RB /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P1_1RB1LA_0LA1RC_0LD1RD_0LB0RB = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1LA_0LA1RC_0LD1RD_0LB0RB, cden, P0_1RB1LA_0LA1RC_0LD1RD_0LB0RB, P1_1RB1LA_0LA1RC_0LD1RD_0LB0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LA_0LA1RC_0LD1RD_0LB0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1LA_0LA1RC_0LD1RD_0LB0RB p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1LA_0LA1RC_0LD1RD_0LB0RB Z0_1RB1LA_0LA1RC_0LD1RD_0LB0RB Z1_1RB1LA_0LA1RC_0LD1RD_0LB0RB 0 2
               run_z_1RB1LA_0LA1RC_0LD1RD_0LB0RB (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1LA_0LA1RC_0LD1RD_0LB0RB p j' q0 E) as (HA & HB).
    exists (6 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LA_0LA1RC_0LD1RD_0LB0RB P0_1RB1LA_0LA1RC_0LD1RD_0LB0RB P1_1RB1LA_0LA1RC_0LD1RD_0LB0RB 6 8
               run_p_1RB1LA_0LA1RC_0LD1RD_0LB0RB (Ap_Alph_011_111_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB1LA_0LA1RC_0LD1RD_0LB0RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LA_0LA1RC_0LD1RD_0LB0RB.
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (H1 & _).
  unfold Cc_1RB1LA_0LA1RC_0LD1RD_0LB0RB, cden, B0_1RB1LA_0LA1RC_0LD1RD_0LB0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LA_0LA1RC_0LD1RD_0LB0RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LA_0LA1RC_0LD1RD_0LB0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0LA1RC_0LD1RD_0LB0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_0LA1RC_0LD1RD_0LB0RB
             = (StB, (rep [S0;S1;S1] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_1RB1LA_0LA1RC_0LD1RD_0LB0RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0;S1;S1] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1LA_0LA1RC_0LD1RD_0LB0RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1LA_0LA1RC_0LD1RD_0LB0RB. reflexivity.
Qed.

Lemma gsn_1RB1LA_0LA1RC_0LD1RD_0LB0RB : forall v i q0, cview v = (i, Some q0) ->
