Lemma gen_1RB1LA_0LA1RC_0LD1RD_0LB0RB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_1RB1LA_0LA1RC_0LD1RD_0LB0RB) = lift (Cin (Pos.succ v)).
