Lemma lapin_1RB1LA_0LA1RC_0LD1RD_0LB0RB : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 8), (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_1RB1LA_0LA1RC_0LD1RD_0LB0RB).
  split; [lia|]. split; [| exact (gen_1RB1LA_0LA1RC_0LD1RD_0LB0RB v i q0 E)].
  rewrite (gsn_1RB1LA_0LA1RC_0LD1RD_0LB0RB v i q0 E).
  exact (srun_sound tm false true chn_1RB1LA_0LA1RC_0LD1RD_0LB0RB AI0_1RB1LA_0LA1RC_0LD1RD_0LB0RB AI1_1RB1LA_0LA1RC_0LD1RD_0LB0RB 6 8
           run_inner_1RB1LA_0LA1RC_0LD1RD_0LB0RB (Ap_Alph_101_111_1 q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_1RB1LA_0LA1RC_0LD1RD_0LB0RB : forall j, lift (cden [] [] j BB1_1RB1LA_0LA1RC_0LD1RD_0LB0RB) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LA_0LA1RC_0LD1RD_0LB0RB = (StC, (rep [S1;S0;S1] j ++ [S1;S1], S0, []))).
  { unfold cden, BB1_1RB1LA_0LA1RC_0LD1RD_0LB0RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S1;S0;S1] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB1LA_0LA1RC_0LD1RD_0LB0RB. rewrite epow2_1RB1LA_0LA1RC_0LD1RD_0LB0RB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LA_0LA1RC_0LD1RD_0LB0RB. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LA_0LA1RC_0LD1RD_0LB0RB : forall j, Cin (fill (pow2 j)) = cden [] [] j BM0_1RB1LA_0LA1RC_0LD1RD_0LB0RB.
Proof.
  intro j.
  destruct (Alph_101_111_1.cview_none_Alph_101_111_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1LA_0LA1RC_0LD1RD_0LB0RB, cden, BM0_1RB1LA_0LA1RC_0LD1RD_0LB0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

