(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo2_1RB1LA_0LA1RC_0LD1RD_0LB0RB : forall j, lift (cden [] [] j BM1_1RB1LA_0LA1RC_0LD1RD_0LB0RB) = lift (Cin2 (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BM1_1RB1LA_0LA1RC_0LD1RD_0LB0RB = (StD, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, []))).
  { unfold cden, BM1_1RB1LA_0LA1RC_0LD1RD_0LB0RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin2 (pow2 j) = (StD, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, []))).
  { unfold Cin2_1RB1LA_0LA1RC_0LD1RD_0LB0RB. rewrite epow22_1RB1LA_0LA1RC_0LD1RD_0LB0RB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LA_0LA1RC_0LD1RD_0LB0RB. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi2_1RB1LA_0LA1RC_0LD1RD_0LB0RB : forall j, Cin2 (fill (pow2 j)) = cden [] [] j BE0_1RB1LA_0LA1RC_0LD1RD_0LB0RB.
Proof.
