Lemma firex_1RB1LA_0LA1RC_0LD1RD_0LB0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LA_0LA1RC_0LD1RD_0LB0RB = Some t ->
