Lemma fireo_1RB1LA_0LA1RC_0LD1RD_0RB0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0LA1RC_0LD1RD_0RB0RB = Some t ->
