    exact (srun_sound tm true true chb_1RB1LA_0LA1RC_0LD1RD_0RB0RB B0_1RB1LA_0LA1RC_0LD1RD_0RB0RB BB1_1RB1LA_0LA1RC_0LD1RD_0RB0RB 6 4
             run_boot_1RB1LA_0LA1RC_0LD1RD_0RB0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
