  unfold Cin_1RB1LA_0LA1RC_0LD1RD_1LC0RB, cden, BE0_1RB1LA_0LA1RC_0LD1RD_1LC0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LA_0LA1RC_0LD1RD_1LC0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB1LA_0LA1RC_0LD1RD_1LC0RB p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LA_0LA1RC_0LD1RD_1LC0RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LA_0LA1RC_0LD1RD_1LC0RB p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_1RB1LA_0LA1RC_0LD1RD_1LC0RB).
    split; [lia|]. split; [| exact (gbo_1RB1LA_0LA1RC_0LD1RD_1LC0RB j)].
    rewrite (gso_1RB1LA_0LA1RC_0LD1RD_1LC0RB p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LA1RC_0LD1RD_1LC0RB B0_1RB1LA_0LA1RC_0LD1RD_1LC0RB BB1_1RB1LA_0LA1RC_0LD1RD_1LC0RB 6 4
             run_boot_1RB1LA_0LA1RC_0LD1RD_1LC0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 13), (cden [] [] j B1_1RB1LA_0LA1RC_0LD1RD_1LC0RB).
    split; [| exact (geo_1RB1LA_0LA1RC_0LD1RD_1LC0RB p j E)].
    rewrite (gxi_1RB1LA_0LA1RC_0LD1RD_1LC0RB j).
    exact (srun_sound tm true true che_1RB1LA_0LA1RC_0LD1RD_1LC0RB BE0_1RB1LA_0LA1RC_0LD1RD_1LC0RB B1_1RB1LA_0LA1RC_0LD1RD_1LC0RB 6 13
             run_exit_1RB1LA_0LA1RC_0LD1RD_1LC0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LA_0LA1RC_0LD1RD_1LC0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_0LA1RC_0LD1RD_1LC0RB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LA_0LA1RC_0LD1RD_1LC0RB p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_0LA1RC_0LD1RD_1LC0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 1.
  assert (H : match csteps tm 1 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 1 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LA_0LA1RC_0LD1RD_1LC0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0LA1RC_0LD1RD_1LC0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_0LA1RC_0LD1RD_1LC0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0LA1RC_0LD1RD_1LC0RB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LA_0LA1RC_0LD1RD_1LC0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LA_0LA1RC_0LD1RD_1LC0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LA_0LA1RC_0LD1RD_1LC0RB t p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_1RB1LA_0LA1RC_0LD1RD_1LC0RB). split;
      [| exact (gbo_1RB1LA_0LA1RC_0LD1RD_1LC0RB j)].
    rewrite (gso_1RB1LA_0LA1RC_0LD1RD_1LC0RB p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LA1RC_0LD1RD_1LC0RB B0_1RB1LA_0LA1RC_0LD1RD_1LC0RB BB1_1RB1LA_0LA1RC_0LD1RD_1LC0RB 6 4
             run_boot_1RB1LA_0LA1RC_0LD1RD_1LC0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LA_0LA1RC_0LD1RD_1LC0RB xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LA_0LA1RC_0LD1RD_1LC0RB j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_0LA1RC_0LD1RD_1LC0RB : forall t, ~ In t pins_1RB1LA_0LA1RC_0LD1RD_1LC0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LA_0LA1RC_0LD1RD_1LC0RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LA_0LA1RC_0LD1RD_1LC0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LA_0LA1RC_0LD1RD_1LC0RB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LA_0LA1RC_0LD1RD_1LC0RB
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LA_0LA1RC_0LD1RD_1LC0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LA_0LA1RC_0LD1RD_1LC0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1]).
    vm_compute; reflexivity.
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_0LA1RC_0LD1RD_1LC0RB (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_0LA1RC_0LD1RD_1LC0RB [SRotL 1; SWin 5; SCycL 3 0; SWin 1; SWinL 3] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_0LA1RC_0LD1RD_1LC0RB (StD, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_0LA1RC_0LD1RD_1LC0RB [SRotL 1; SWin 5; SCycL 3 0; SWin 1; SWinL 3; SCycR 3; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1LA_0LA1RC_0LD1RD_1LC0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB1LA_0LA1RC_0LD1RD_1LC0RB : NeverQuasiHaltsTr tm_1RB1LA_0LA1RC_0LD1RD_1LC0RB.
Proof.
  apply (glue_neverqhtr tm_1RB1LA_0LA1RC_0LD1RD_1LC0RB pins_1RB1LA_0LA1RC_0LD1RD_1LC0RB Cc 1).
  - exact boot_1RB1LA_0LA1RC_0LD1RD_1LC0RB.
  - intros p _. apply lap_1RB1LA_0LA1RC_0LD1RD_1LC0RB.
  - intros t Ht p _. apply fire_1RB1LA_0LA1RC_0LD1RD_1LC0RB. exact Ht.
Qed.

Theorem nonhalt_1RB1LA_0LA1RC_0LD1RD_1LC0RB : NonHalt tm_1RB1LA_0LA1RC_0LD1RD_1LC0RB.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB1LA_0LA1RC_0LD1RD_1LC0RB. Qed.

