Lemma lapi_1RB1LA_0LA1RC_0LD1RD_1LD0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
