  split; [lia|]. split; [| exact (gei_1RB1LA_0LA1RC_0LD1RD_1RA0RB p j q0 E)].
  rewrite (gsi_1RB1LA_0LA1RC_0LD1RD_1RA0RB p j q0 E).
  exact (srun_sound tm false true chi_1RB1LA_0LA1RC_0LD1RD_1RA0RB A0_1RB1LA_0LA1RC_0LD1RD_1RA0RB A1_1RB1LA_0LA1RC_0LD1RD_1RA0RB 6 50
           run_int_1RB1LA_0LA1RC_0LD1RD_1RA0RB (Ap_Alph_110_111_111 q0 ++ [S0]) [] j
