Lemma geo_1RB1LA_0LA1RC_0LD1RD_1RA0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0LA1RC_0LD1RD_1RA0RB) = lift (Cc (Pos.succ p)).
