  - destruct (lapi_1RB1LA_0LA1RC_0RB1RD_0LB0RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_0LA1RC_0RB1RD_0LB0RB B0_1RB1LA_0LA1RC_0RB1RD_0LB0RB B1_1RB1LA_0LA1RC_0RB1RD_0LB0RB 6 30 p j' [] []).
    + exact run_ovf_1RB1LA_0LA1RC_0RB1RD_0LB0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_0LA1RC_0RB1RD_0LB0RB p j' E).
    + exact (geo_1RB1LA_0LA1RC_0RB1RD_0LB0RB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_0LA1RC_0RB1RD_0LB0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 46.
  assert (H : match csteps tm 46 c0 with
