  rewrite (gsi_1RB1LA_0LA1RC_0RB1RD_1RB0RB p j q0 E).
  exact (srun_sound tm false true chi_1RB1LA_0LA1RC_0RB1RD_1RB0RB A0_1RB1LA_0LA1RC_0RB1RD_1RB0RB A1_1RB1LA_0LA1RC_0RB1RD_1RB0RB 6 26
