Lemma geo_1RB1LA_0LA1RC_0RB1RD_1RB0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0LA1RC_0RB1RD_1RB0RB) = lift (Cc (Pos.succ p)).
