  intros p j E. destruct (Alph_110_111_111.cview_none_Alph_110_111_111 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_0LA1RC_0RB1RD_1RB0RB
             = (StA, (rep [S1;S1;S0] (S j) ++ [S1;S1;S1], S1, ([S1;S1;S1]) ++ [S0]))).
  { unfold cden, B1_1RB1LA_0LA1RC_0RB1RD_1RB0RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
