  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB1LA_0LA1RC_0RD0RB_0LD1LA. rewrite epow2_1RB1LA_0LA1RC_0RD0RB_0LD1LA.
