Lemma gz_1RB1LA_0LA1RC_0RD1RD_0LB0RB : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_1RB1LA_0LA1RC_0RD1RD_0LB0RB /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_1RB1LA_0LA1RC_0RD1RD_0LB0RB = Cc (Pos.succ p).
