  unfold Cc_1RB1LA_0LA1RC_0RD1RD_0LB0RB, cden, P0_1RB1LA_0LA1RC_0RD1RD_0LB0RB, P1_1RB1LA_0LA1RC_0RD1RD_0LB0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
