    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0LA1RC_0RD1RD_0LB0RB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma firex_1RB1LA_0LA1RC_0RD1RD_0LB0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LA_0LA1RC_0RD1RD_0LB0RB = Some t ->
