    split; [lia|]. split; [| exact (gbo_1RB1LA_0LA1RC_0RD1RD_0LB0RB j)].
    rewrite (gso_1RB1LA_0LA1RC_0RD1RD_0LB0RB p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LA1RC_0RD1RD_0LB0RB B0_1RB1LA_0LA1RC_0RD1RD_0LB0RB BB1_1RB1LA_0LA1RC_0RD1RD_0LB0RB 6 4
             run_boot_1RB1LA_0LA1RC_0RD1RD_0LB0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LA_0LA1RC_0RD1RD_0LB0RB p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (6 * j + 8), (cden [] [] j BM1_1RB1LA_0LA1RC_0RD1RD_0LB0RB).
    split; [| exact (gbo2_1RB1LA_0LA1RC_0RD1RD_0LB0RB j)].
    rewrite (gxi_1RB1LA_0LA1RC_0RD1RD_0LB0RB j).
    exact (srun_sound tm true true chm_1RB1LA_0LA1RC_0RD1RD_0LB0RB BM0_1RB1LA_0LA1RC_0RD1RD_0LB0RB BM1_1RB1LA_0LA1RC_0RD1RD_0LB0RB 6 8
             run_shift_1RB1LA_0LA1RC_0RD1RD_0LB0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
