  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LA_0LA1RC_0RD1RD_0LB0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
