    rewrite (srun_sound tm false true chz_1RB1LA_0LA1RC_0RD1RD_0LD0RB Z0_1RB1LA_0LA1RC_0RD1RD_0LD0RB Z1_1RB1LA_0LA1RC_0RD1RD_0LD0RB 0 2
               run_z_1RB1LA_0LA1RC_0RD1RD_0LD0RB (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1LA_0LA1RC_0RD1RD_0LD0RB p j' q0 E) as (HA & HB).
    exists (6 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LA_0LA1RC_0RD1RD_0LD0RB P0_1RB1LA_0LA1RC_0RD1RD_0LD0RB P1_1RB1LA_0LA1RC_0RD1RD_0LD0RB 6 8
               run_p_1RB1LA_0LA1RC_0RD1RD_0LD0RB (Ap_Alph_011_111_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
