    apply (lap_of_run tm Cc true true cho_1RB1LA_0LA1RC_1LA1RD_0LB0RB B0_1RB1LA_0LA1RC_1LA1RD_0LB0RB B1_1RB1LA_0LA1RC_1LA1RD_0LB0RB 6 22 p j' [] []).
    + exact run_ovf_1RB1LA_0LA1RC_1LA1RD_0LB0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_0LA1RC_1LA1RD_0LB0RB p j' E).
    + exact (geo_1RB1LA_0LA1RC_1LA1RD_0LB0RB p j' E).
    + lia.
