Lemma geo_1RB1LA_0LA1RC_1LA1RD_0RB0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0LA1RC_1LA1RD_0RB0LC) = lift (Cc (Pos.succ p)).
