Lemma gei_1RB1LA_0LA1RC_1LD0RB____1LA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB1LA_0LA1RC_1LD0RB____1LA) = lift (Cc (Pos.succ p)).
Proof.
