    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_0LA1RC_1LD0RB____1LA B0_1RB1LA_0LA1RC_1LD0RB____1LA B1_1RB1LA_0LA1RC_1LD0RB____1LA 4 19 p j' [] []).
    + exact run_ovf_1RB1LA_0LA1RC_1LD0RB____1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_0LA1RC_1LD0RB____1LA p j' E).
    + exact (geo_1RB1LA_0LA1RC_1LD0RB____1LA p j' E).
    + lia.
