  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LA1RC_1LD0RB____1LA [SWin 2; SWinR 6; SCycL 2 0; SWin 6; SCycR 2; SWin 4] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB1LA_0LA1RC_1LD0RB____1LA : NeverQuasiHaltsTr tm_1RB1LA_0LA1RC_1LD0RB____1LA.
