(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_1RB1LA_0LA1RC_1LD0RB____1LC : forall j, lift (cden [] [] j BB1_1RB1LA_0LA1RC_1LD0RB____1LC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LA_0LA1RC_1LD0RB____1LC = (StA, (rep [S1;S0] j ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB1LA_0LA1RC_1LD0RB____1LC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB1LA_0LA1RC_1LD0RB____1LC. rewrite epow2_1RB1LA_0LA1RC_1LD0RB____1LC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
