               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB1LA_0LA1RC_1LD0RB____1LC. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LA_0LA1RC_1LD0RB____1LC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LA_0LA1RC_1LD0RB____1LC p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB1LA_0LA1RC_1LD0RB____1LC).
    split; [lia|]. split; [| exact (gbo_1RB1LA_0LA1RC_1LD0RB____1LC j)].
    rewrite (gso_1RB1LA_0LA1RC_1LD0RB____1LC p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LA1RC_1LD0RB____1LC B0_1RB1LA_0LA1RC_1LD0RB____1LC BB1_1RB1LA_0LA1RC_1LD0RB____1LC 4 8
             run_boot_1RB1LA_0LA1RC_1LD0RB____1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (8 * j + 19), (cden [] [] j B1_1RB1LA_0LA1RC_1LD0RB____1LC).
    split; [| exact (geo_1RB1LA_0LA1RC_1LD0RB____1LC p j E)].
    rewrite (gxi_1RB1LA_0LA1RC_1LD0RB____1LC j).
    exact (srun_sound tm true true che_1RB1LA_0LA1RC_1LD0RB____1LC BE0_1RB1LA_0LA1RC_1LD0RB____1LC B1_1RB1LA_0LA1RC_1LD0RB____1LC 8 19
             run_exit_1RB1LA_0LA1RC_1LD0RB____1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_1RB1LA_0LA1RC_1LD0RB____1LC : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_1RB1LA_0LA1RC_1LD0RB____1LC = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
  apply (vis_via_fill tm Cc Cin lapin_1RB1LA_0LA1RC_1LD0RB____1LC q p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB1LA_0LA1RC_1LD0RB____1LC). split;
      [| exact (gbo_1RB1LA_0LA1RC_1LD0RB____1LC j)].
    rewrite (gso_1RB1LA_0LA1RC_1LD0RB____1LC p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LA1RC_1LD0RB____1LC B0_1RB1LA_0LA1RC_1LD0RB____1LC BB1_1RB1LA_0LA1RC_1LD0RB____1LC 4 8
             run_boot_1RB1LA_0LA1RC_1LD0RB____1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (vis_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (vis_of_run tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LA_0LA1RC_1LD0RB____1LC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LA_0LA1RC_1LD0RB____1LC j)].
Qed.



(** ** The lap *)

Lemma lap_1RB1LA_0LA1RC_1LD0RB____1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_0LA1RC_1LD0RB____1LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LA_0LA1RC_1LD0RB____1LC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_0LA1RC_1LD0RB____1LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 11.
  assert (H : match csteps tm 11 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 11 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LA_0LA1RC_1LD0RB____1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0LA1RC_1LD0RB____1LC = Some t ->
  forall p j, cview p = (S j, None) ->
