    apply (lap_of_run tm Cc true true cho_1RB1LA_0LA1RC_1RB0LD_0RB1RD B0_1RB1LA_0LA1RC_1RB0LD_0RB1RD B1_1RB1LA_0LA1RC_1RB0LD_0RB1RD 6 27 p j' [] []).
    + exact run_ovf_1RB1LA_0LA1RC_1RB0LD_0RB1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_0LA1RC_1RB0LD_0RB1RD p j' E).
    + exact (geo_1RB1LA_0LA1RC_1RB0LD_0RB1RD p j' E).
    + lia.
